/**
 * @summary Cross-assessment marking queue for the current educator (admin sees all).
 */
export const getGetStudioMarkingQueueUrl = (
  params?: GetStudioMarkingQueueParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/studio/marking-queue?${stringifiedParams}`
    : `/api/studio/marking-queue`;
};

